<script lang="ts">
  import { getContext } from 'svelte';
  import { experienceKey, formatMoney, type Experience } from '#lib/selection.ts';
  import { membershipCopy } from '#lib/memberships.ts';
  import { contentKey, privateGroups, type ContentState } from '#lib/content-schema.ts';
  import type { Lang } from '#lib/site.ts';
  import Icon from './Icon.svelte';
  let { lang }: { lang: Lang } = $props();
  const c = $derived(membershipCopy[lang]);
  const experience = getContext<Experience>(experienceKey);
  const content = getContext<ContentState>(contentKey);
  const catalog = $derived(content.data.catalog);
  const options = $derived(privateGroups(catalog, experience.selection.discipline));
  const participants = $derived(experience.selection.participants), lessons = $derived(experience.selection.lessons);
  function choosePeople(value: number) { experience.selection.participants = value; if (!options.find(group => group.participants === value)?.packages.some(pack => pack.lessons === lessons)) experience.selection.lessons = options.find(group => group.participants === value)?.packages[0]?.lessons ?? 8; experience.explicit = true; }
  const group = $derived(options.find(group => group.participants === participants) ?? options[0]);
  const chosen = $derived(group?.packages.find(pack => pack.lessons === lessons) ?? group?.packages[0]);
  const money = (amount: number, decimals = 0) => formatMoney(amount, lang, catalog.currency, decimals);
  const duration = (months: number) => lang === 'en' && months === 1 ? '1 month' : `${months} ${c.month}`;
</script>

<div id="private-lessons" class="private-lessons">
{#if group && chosen}
  <fieldset class="private-people" style={`--people-count:${Math.max(options.length,1)}`}><legend>{c.people}</legend>{#each options as option}<label class:active={participants === option.participants}><input type="radio" name="private-people" value={option.participants} checked={participants === option.participants} onchange={() => choosePeople(option.participants)}/><span>{option.participants} {lang === 'en' && option.participants === 1 ? 'person' : c.person}</span></label>{/each}</fieldset>
  <div class="private-layout"><div class="private-intro"><span class="eyebrow">SELF CONTROL / PERSONAL TRAINING</span><h4>{participants === 1 ? c.individual : c.together}</h4><p>{c.intro}</p><div class="private-facts"><span><Icon name="clock" size={17}/>{group.sessionMinutes} {c.minute}</span><span><Icon name="training" size={17}/>{participants} {lang === 'en' && participants === 1 ? 'person' : c.person}</span></div><p class="private-price-note">{c.priceNote}</p></div>
  <div class="private-offers"><fieldset class="private-package-list"><legend class="sr-only">{c.packages}</legend>{#each group.packages as pack}<label class="private-package" class:chosen={chosen.lessons === pack.lessons}><input type="radio" name="private-package" value={pack.lessons} checked={chosen.lessons === pack.lessons} onchange={() => { experience.selection.lessons = pack.lessons; experience.explicit = true; }}/><span class="private-package-name"><strong>{pack.lessons} {c.lessons}</strong><small>{pack.validityMonths ? `${c.validity}: ${duration(pack.validityMonths)}` : pack.lessons === 1 ? c.single : `${c.validity}: ${lang === 'tr' ? 'belirtilmedi' : 'not specified'}`}</small></span><span class="private-package-price"><strong>{money(pack.price)}</strong><small>{c.perPerson}</small></span></label>{/each}</fieldset>
  <div class="private-summary" aria-live="polite"><span class="eyebrow">{c.selected} / {chosen.lessons} {c.lessons}</span><div class="private-summary-total"><span>{c.total}</span>{#key chosen.price}<strong class="price-update">{money(chosen.price)}</strong>{/key}</div><p>{money(chosen.price / chosen.lessons, 2)} {c.lesson} · {group.sessionMinutes} {c.minute}</p><button class="button solid" onclick={() => experience.enquiryOpen = true}>{c.ask}<Icon name="diagonal" size={19}/></button></div></div></div>
  <p class="pricing-note">{catalog.status === 'sample' ? c.note : lang === 'tr' ? 'Özel ders saatleri antrenörle birlikte belirlenir. Ücretler kişi başı paket toplamıdır.' : 'Session times are agreed with the trainer. Prices are the package total per person.'}</p>
{:else}<p class="pricing-note">{lang === 'tr' ? 'Bu kapsam için özel ders paketleri henüz yayımlanmadı.' : 'Private lesson packages have not been published for this scope.'}</p>{/if}
</div>

<style>
.price-update{animation:price-in .2s ease-out}@keyframes price-in{from{opacity:.3;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}

.private-people{border:0;padding:0;margin:0 0 26px;display:grid;grid-template-columns:repeat(var(--people-count,4),minmax(0,1fr));gap:10px}.private-people legend{font-size:13px;padding:0;margin-bottom:14px}.private-people label{display:flex;align-items:center;justify-content:center;gap:12px;min-height:56px;padding:12px;background:transparent;border:1px solid var(--line);cursor:pointer;font-size:14px;transition:background .2s}.private-people label.active{background:var(--signal);color:var(--button-fg);border-color:var(--signal)}input[type=radio]{width:18px;height:18px;accent-color:var(--signal);margin:0;flex-shrink:0}.private-people input{accent-color:var(--button-fg)}.private-people label:focus-within,.private-package:focus-within{outline:2px solid var(--signal);outline-offset:4px}.private-layout{display:grid;grid-template-columns:1fr 1.25fr;border:1px solid var(--line)}.private-intro{padding:38px;background:var(--surface)}.private-intro>h4{font:800 clamp(40px,4.5vw,65px)/1 Barlow,Impact,sans-serif;letter-spacing:-.015em;margin:28px 0 20px}.private-intro>p{font-size:14px;color:var(--muted);max-width:340px}.private-facts{display:grid;gap:14px;margin:30px 0;padding-block:24px;border-block:1px solid var(--line)}.private-facts>span{display:flex;align-items:center;gap:12px;font-size:13px}.private-price-note{font-size:13px}.private-offers{padding:28px;min-width:0}.private-package-list{border:0;padding:0;margin:0;display:grid;gap:12px;min-width:0}.private-package{display:flex;align-items:center;gap:16px;text-align:left;width:100%;padding:20px;background:transparent;color:var(--fg);border:1px solid var(--line);min-height:104px;cursor:pointer;transition:border-color .2s,background .2s}.private-package.chosen{border-color:var(--signal);background:var(--surface)}.private-package-name,.private-package-price{display:flex;flex-direction:column;gap:8px;min-width:0}.private-package-name>strong{font-size:15px;font-weight:500}.private-package small{font-size:12px;line-height:1.6;color:var(--muted)}.private-package-price{margin-left:auto;text-align:right;flex-shrink:0}.private-package-price>strong{font:800 34px/1 Barlow,Impact,sans-serif;white-space:nowrap;font-variant-numeric:tabular-nums}.private-summary{padding-top:25px;margin-top:25px;border-top:1px solid var(--line)}.private-summary>.eyebrow{font-size:11px;color:var(--signal)}.private-summary-total{display:flex;justify-content:space-between;align-items:baseline;gap:15px;margin:18px 0 12px;flex-wrap:wrap}.private-summary-total>span{font-size:13px;color:var(--muted)}.private-summary-total>strong{font:800 44px/1 Barlow,Impact,sans-serif}.private-summary>p{font-size:13px;color:var(--muted)}.private-summary .button{width:100%;margin-top:22px;font-size:13px}.private-lessons>.pricing-note{margin-top:20px;font-size:12px}.private-people:focus-within{scroll-margin-block:110px}
@media(max-width:700px){.private-people{gap:8px;margin-bottom:20px}.private-people label{flex-direction:column;gap:8px;padding:12px 4px;font-size:13px}.private-people input{width:16px;height:16px}.private-layout{grid-template-columns:1fr}.private-offers{grid-row:1;padding:18px}.private-intro{grid-row:2;border-top:1px solid var(--line);padding:24px}.private-intro>h4{font-size:43px;margin:22px 0 15px}.private-facts{display:flex;flex-wrap:wrap;gap:20px;margin:22px 0;padding-block:18px}.private-package{padding:18px 14px;gap:12px}.private-package-name>strong{font-size:14px}.private-package small{font-size:12px}.private-package-price>strong{font-size:31px}.private-summary-total>strong{font-size:40px}}
@media(max-width:360px){.private-offers{padding:12px}.private-package{padding:16px 12px;gap:9px;flex-wrap:wrap}.private-package-name{flex:1}.private-package-price{margin-left:27px;flex-basis:100%;flex-direction:row;align-items:baseline;justify-content:space-between}.private-package-price>strong{font-size:32px}.private-summary-total>strong{font-size:36px}}
</style>
